import {RESEARCH_PATH,RESEARCH_VERSION,RESEARCH_STORAGE_PREFIX,researchDraftFor,restoreResearchDraft,loadAnnualResearchCase,calculateResearchOperating,terminalNormalizedDraft,researchTimingResult,researchSensitivity,exportResearchCase} from './research-model.js';
import {researchBridgeDefinition,calculateResearchBridge,researchBridgeSensitivity} from './research-claims.js';
import {researchSummaries} from './research-summaries.js';

const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const finite=x=>typeof x==='number'&&Number.isFinite(x);
const num=(n,d=1)=>finite(n)?n.toLocaleString('en-US',{maximumFractionDigits:d}):'Not computed';
const pct=n=>finite(n)?`${num(n*100,2)}%`:'Not meaningful';
const amount=(n,c)=>finite(n)?`${num(n/1000,2)}bn ${esc(c)}`:'Not computed';
const plain=n=>finite(n)?String(Number(n.toPrecision(12))):'';
const link=(path,text)=>`<a href="${esc(path)}" target="_blank" rel="noopener">${esc(text)} ↗</a>`;
const table=(caption,headers,rows)=>`<div class="research-table-scroll" tabindex="0" role="region" aria-label="${esc(caption)}"><table class="research-table"><caption>${esc(caption)}</caption><thead><tr>${headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((cell,i)=>i===0?`<th scope="row">${cell}</th>`:`<td>${cell}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const list=xs=>`<ul>${(xs||[]).map(x=>`<li>${esc(typeof x==='string'?x:x.message||x.description||JSON.stringify(x))}</li>`).join('')}</ul>`;
const input=(key,value,label,{scale=1,step='any',min,max,group='annual',index}={})=>`<input type="number" inputmode="decimal" data-research-input="${group}" data-field="${esc(key)}" data-scale="${scale}" ${index===undefined?'':`data-index="${index}"`} value="${plain(finite(value)?value*scale:null)}" step="${step}" ${min===undefined?'':`min="${min}"`} ${max===undefined?'':`max="${max}"`} aria-label="${esc(label)}">`;
function bridgeSensitivityHTML(d,timing){
 if(!finite(timing.enterprise))return '';
 try{const rows=researchBridgeSensitivity(d,timing.enterprise,{...(d.bridgeInputs||{}),calculationDate:timing.date});return `<details><summary>Named capital-allocation sensitivities</summary>${table('Common allocation per share; conditional source-date scenarios',['Scenario',`${d.currency} / share`],rows.map(r=>[esc(r.label),finite(r.rawPerShare)?num(r.rawPerShare,2):'Not computed']))}<p class="micro">These cases are distinct treatments, not a probability range. Principal-only convertible stress omits option value. Unpriced claims are still disclosed in every case.</p></details>`;}catch{return '';}
}
function capitalEvidenceHTML(c,d){
 const rows=c.annual.flatMap(r=>Object.entries(r.capitalComponents||{}).filter(([,v])=>finite(v)).map(([key,value])=>[String(r.year),esc(key.replace(/_/g,' ')),num(value,2)]));
 return `<details class="research-card"><summary>Original gross-to-net investment evidence</summary><p>Authoritative annual net investment is deducted once. ${d.userEdited?'Your edited path may no longer reconcile to these original components.':'These components belong to the preserved reviewed case.'}</p>${rows.length?table('Original capital components, company currency millions',['Year','Component','Amount'],rows):'<p>No complete annual gross-capex, D&A, lease and working-capital decomposition is supplied for this selected case. Its net-investment schedule is an analytical proxy, not proof of a maintenance budget.</p>'}<p class="micro">Missing later components are unmodeled, not zero spending. Customer advances and finance-lease effects enter once under the linked company policy. SBC is already an economic cost in EBIT; its cash-funding addback does not raise economic FCFF.</p>${link(`./data/renewed-research-2026-10-17/evidence-${c.ticker}.html#selected-case`,'Investment provenance and bounded gaps')}</details>`;
}

export function researchResultsHTML(c,d,{identityError=null}={}){
 if(identityError)return `<div class="error"><h2>Saved draft needs attention</h2><p>${esc(identityError)}</p><p>Your saved draft has been retained. Export it, or explicitly load the reviewed case. Undo restores the full previous draft.</p></div>`;
 try{
  const r=calculateResearchOperating(d),timing=researchTimingResult(d,r),s=researchSensitivity(d);
  let bridge=null;try{if(timing.status!=='incomplete')bridge=calculateResearchBridge(d,timing.enterprise,{...(d.bridgeInputs||{}),calculationDate:timing.date});}catch(e){bridge={message:e.message,warnings:['The operating calculation remains valid; the equity bridge needs correction.']};}
  const equity=bridge?.equity,perShare=bridge?.rawPerShare;
  const bridgeReady=finite(equity)&&finite(perShare);
  const terminalWarning=r.warnings.length?`<div class="research-warning"><b>Model transitions to inspect</b>${list(r.warnings)}</div>`:'';
  return `<section class="research-value" aria-label="Conditional researched operating value"><span class="eyebrow">${d.userEdited?'EDITED ANNUAL SCENARIO':'REVIEWED ANNUAL RESEARCH'} · ${esc(d.currency)} MILLIONS IN TABLES</span><h2>${timing.status==='scenario'?'As-of operating scenario':'Forecast-origin operating value'}</h2><p class="research-big-value">${amount(timing.status==='incomplete'?r.enterprise:timing.enterprise,d.currency)}</p><p class="research-date-line">${timing.status==='scenario'?`Scenario date ${esc(timing.date)}`:`Discount origin ${esc(d.discountOrigin)}`} · information through ${esc(d.informationAsOf)}</p><p>${timing.status==='incomplete'?'Origin value remains visible while the as-of bridge is incomplete.':esc(timing.label)}. ${timing.status==='origin'?(c.anchor.kind==='management_full_year_forecast'?'The anchor is a management full-year forecast, not a reported actual. An October value needs the remaining pre-origin cash-flow stub.':'This uses later research information for the reported anchor; it is not a value that was knowable on the anchor date.'):''}</p>${timing.status==='incomplete'?`<div class="research-warning"><b>As-of value not computed</b><p>${esc(timing.message)}</p></div>`:''}<div class="research-stat-grid"><div><span>Forecast horizon</span><b>${r.rows.length} years</b></div><div><span>Terminal PV / origin EV</span><b>${pct(r.terminalShare)}</b></div><div><span>Peak economic deficit</span><b>${amount(r.peakEconomicDeficit,d.currency)}</b></div></div><p class="micro">${r.negativeFCFFYears} negative-FCFF years. The cumulative deficit is before financing, reserves, coupons and other uses; it is never deducted again as debt.</p>${r.enterprise<0?'<div class="research-warning"><b>Negative operating value is preserved.</b><p>This conditional business path consumes more capital than its discounted earnings support. It is not a traded-security price or a prediction of default.</p></div>':''}</section>
  <section class="research-card research-equity"><h2>From operations to common equity</h2>${bridgeReady?`<p class="research-equity-value">${num(perShare,2)} ${esc(d.currency)} <small>/ ${d.currency==='TWD'?'ordinary share':'common share'}</small></p><p><b>Conditional source-date common allocation</b></p><p>Signed common equity ${amount(equity,d.currency)}${equity<0?`; limited-liability display floor ${num(bridge.flooredPerShare??0,2)} per share`:''}.</p>`:`<p class="research-warning">${esc(bridge?.message||bridge?.reason||bridge?.reasons?.join(' ')||'Common-equity output is incomplete. The operating scenario above remains available.')}</p>`}${bridge?`<p class="micro">Capital reference ${esc(bridge.capitalReferenceDate||bridge.referenceDate||'see line items')} · share reference ${esc(bridge.shareReferenceDate||'see share basis')}. ${esc(bridge.securityBasis||bridge.shareBasis||'')}</p>${bridge.warnings?.length?list(bridge.warnings.slice(0,2)):''}${bridge.warnings?.length>2?`<details><summary>Claim policy and unresolved assumptions</summary>${list(bridge.warnings.slice(2))}</details>`:''}${bridge.rows?.length?`<details><summary>Dated equity-bridge line items</summary>${table('Equity bridge, currency millions',['Item','Amount','Treatment'],bridge.rows.map(x=>[esc(x.label||x.name||x.id),num(x.amount??x.value,2),esc(x.kind+' · '+x.referenceDate)]))}</details>`:''}`:''}${c.ticker==='AAOI'?'<p>The earlier June TTM Studio model still has its reviewed dated convertible/warrant bridge. This renewed December forecast-origin case needs a separate 2026 capital roll-forward.</p><button class="quiet" data-research-action="legacy">Open prior AAOI source-date model</button>':''}${bridgeSensitivityHTML(d,timing)}<p class="micro">Material omitted claims are named in the policy disclosure. A source-date proxy is not verified current capital. SBC remains an expense in operating profit; future funding and existing awards are separate questions.</p></section>
  ${terminalWarning}<div id="research-simulation-root"></div><section class="research-card"><h2>Capital transition and rate sensitivity</h2><p>Current final explicit-year FCFF ${num(r.rows.at(-1).fcff,1)}m; next terminal-year FCFF ${num(r.terminal.fcff,1)}m. FCFF changes ${pct(r.terminal.fcffGrowth)} while terminal revenue grows ${pct(d.terminal.growth)}.</p>${table('Operating EV sensitivities at forecast origin',['Case','Operating EV'],[['Current annual path',amount(r.enterprise,d.currency)],['Three-year capital normalization v1',amount(s.normalized,d.currency)],['Normalization difference',amount(s.normalizationDelta,d.currency)],...s.rates.filter(x=>x.waccShift!==0).map(x=>[`${x.waccShift>0?'+':'−'}1pp annual and terminal WACC`,amount(x.enterprise,d.currency)])])}<p class="micro">Normalization blends only the last three investment amounts toward NOPAT × g / ROIC and leaves revenue, margin, tax and WACC unchanged. An already consistent endpoint is left alone. This is a separately versioned analytical sensitivity, not automatically a better forecast. MU’s revenue-growth endpoint remains a separate disclosure.</p><button class="quiet" data-research-action="normalize">Load capital-normalized sensitivity</button></section>
  ${capitalEvidenceHTML(c,d)}<details class="research-card"><summary>Every annual cash flow and terminal calculation</summary>${table('Calculated annual operating cash flows, currency millions',['Year','Growth','Revenue','EBIT','Tax','NOPAT','Investment','FCFF','PV'],r.rows.map(x=>[esc(x.year),pct(x.growth),num(x.revenue),num(x.ebit),num(x.tax),num(x.nopat),num(x.reinvestment),num(x.fcff),num(x.pv)]))}${table('Next-year terminal calculation, currency millions',['Revenue','NOPAT','Investment','FCFF','Terminal value','PV'],[[num(r.terminal.revenue),num(r.terminal.nopat),num(r.terminal.reinvestment),num(r.terminal.fcff),num(r.terminal.value),num(r.terminalPV)]])}<p class="micro">Annual tax = max(0, EBIT) × tax rate. FCFF = NOPAT − direct investment. Discount factors compound each annual WACC. Terminal value = terminal NOPAT × (1 − g / ROIC) / (WACC − g). Signed operating and common-equity results are retained.</p></details>`;
 }catch(error){return `<div class="error" role="status"><h2>Check the edited annual inputs</h2><p>${esc(error.message)}</p><p>Results are withheld until the inputs are valid. Your draft is retained.</p></div>`;}
}

export function researchEditorHTML(c,d){
 if(!d||!Array.isArray(d.annual)||!d.terminal)return '<p class="error">This saved draft cannot be edited safely. Export it or explicitly load the reviewed case.</p>';
 const fields=[['revenue','Revenue',1],['margin','EBIT margin %',100],['taxRate','Operating tax %',100],['reinvestment','Net investment',1],['wacc','WACC %',100]];
 const tfields=[['growth','Stable revenue growth %'],['margin','Terminal EBIT margin %'],['taxRate','Terminal tax %'],['roic','Terminal ROIC %'],['wacc','Terminal WACC %']];
 const forecastAnchor=c.anchor.kind==='management_full_year_forecast';
 return `<section class="research-card"><h2>Explicit annual assumptions</h2><p>Values update live. Revenue levels are direct inputs; changing one year does not silently move later revenue. Investment is a direct economic amount, including capital spending less D&A and operating working-capital/lease effects where separately modeled.</p><p class="micro">Source anchor: ${esc(c.anchor.period)} · ${esc(c.anchor.classification)}. First forecast period: ${esc(c.anchor.firstModeledPeriod)}. ${esc(c.anchor.fiscalCalendarCaution)}</p><p class="micro">Scroll the table horizontally to reach every annual input, including WACC.</p>${table('Editable annual schedule, currency millions; rates in percent',['Year',...fields.map(x=>x[1])],d.annual.map((r,i)=>[`${r.year}<small>${esc(r.period)}</small>`,...fields.map(([key,label,scale])=>input(key,r[key],`Year ${r.year} ${label}`,{scale,index:i}))]))}<h3>Terminal assumptions</h3><div class="research-field-grid">${tfields.map(([key,label])=>`<label>${esc(label)}${input(key,d.terminal[key],label,{group:'terminal',scale:100})}</label>`).join('')}</div><p class="micro">Capital-component reconciliations describe the original researched path. After editing investment or margin, check the source economics again; the model does not manufacture a replacement gross-capex budget.</p></section>
 <section class="research-card"><h2>Valuation date and partial-year cash flow</h2><label for="research-timing-mode">Value basis</label><select id="research-timing-mode" data-research-select="timing"><option value="origin" ${d.timing?.mode==='origin'?'selected':''}>Forecast-origin value · no timing assumption</option><option value="as-of-scenario" ${d.timing?.mode==='as-of-scenario'?'selected':''}>Explicit as-of timing scenario</option></select><p>${forecastAnchor?'The revenue base is management’s FY2026 forecast. It is not an observed TTM period. The remaining October 17–December 31 FCFF must be added and the whole future stream discounted over the extra stub interval.':'The annual stream begins at the reported anchor. An October value must remove already-elapsed FCFF before discounting the remaining stream from October.'}</p><div class="research-field-grid"><label>Scenario date<input id="research-asof" type="date" value="${esc(d.timing?.asOf||'2026-10-17')}" data-research-text="asOf" min="2026-10-17"></label><label>${forecastAnchor?'Remaining pre-origin FCFF':'Already-elapsed first-year FCFF'} · millions${input('stubFCFF',d.timing?.stubFCFF,forecastAnchor?'Remaining pre-origin FCFF':'Already elapsed FCFF',{group:'timing'})}</label>${forecastAnchor?`<label>Stub discount rate %${input('stubDiscountRate',d.timing?.stubDiscountRate,'Stub discount rate percent',{group:'timing',scale:100})}</label>`:''}</div><label for="research-stub-reason">Source or explicit timing assumption</label><textarea id="research-stub-reason" rows="3" data-research-text="reason">${esc(d.timing?.reason||'')}</textarea><p class="micro">Blank stays unknown. Entering zero is a substantive assumption and needs an explanation. Calendar proration, if chosen, is an analyst assumption; no realized cash flow is inferred. Dated equity-bridge balances need their own roll-forward.</p></section>
 <section class="research-card"><h2>What changed from the scalar Studio?</h2><p>The legacy Studio remains a separate saved model. These renewed cases use reviewed company-specific revenue and margin schedules, direct annual investment, 10- or 15-year horizons and dated claim adjustments. Those changes can materially change value without any stock-price target.</p><p>MU keeps investing during declining sales. AAOI and NBIS start from explicitly forecast FY2026 anchors. AMZN and GOOG use capital/funding reconciliations. Terminal transitions and uncertainty are shown separately rather than hidden in a smooth curve.</p><p class="micro">Annual Monte Carlo uses the explicit investment-response policy selected in its controls. Fixed starting distributions reproduce the researched case; any uncertainty or parameter relationships are analyst assumptions. The legacy Studio’s simulation remains separate.</p></section>`;
}

export function researchClaimsEditorHTML(c,d){
 const definition=researchBridgeDefinition(c.ticker);if(!definition)return '';
 const controls=definition.optionDefinitions.map(field=>{
  const value=Object.prototype.hasOwnProperty.call(d.bridgeInputs||{},field.key)?d.bridgeInputs[field.key]:field.default;
  if(field.type==='select')return `<label>${esc(field.label)}<select data-research-claim-select="${esc(field.key)}">${field.values.map(v=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;
  const scale=field.max===1?100:1,label=field.label+(scale===100?' · %':'');
  return `<label>${esc(label)}${input(field.key,value,label,{group:'bridge',scale,min:field.min==null?undefined:field.min*scale,max:field.max==null?undefined:field.max*scale})}${value===null?'<small>Required amount is unknown; blank does not mean zero.</small>':''}</label>`;
 }).join('');
 return `<details class="research-card"><summary>Equity-bridge assumptions and sensitivities</summary><p>Capital reference ${esc(definition.referenceDate)}, shares ${esc(definition.shareDate)}. These are disclosed source-date allocation assumptions. An additional claim allowance of zero does not verify that unresolved claims are absent.</p><div class="research-field-grid">${controls}</div><p>${link(definition.sourceUrl,'Original capital-reference source')} · ${link(`./data/renewed-research-2026-10-17/evidence-${c.ticker}.html#claims`,'Complete claims register')}</p><p class="micro">Edits update only this annual research draft. A required convertible premium remains blank until explicitly entered. Gross-share stresses are not option valuations. AAOI and NBIS require date-consistent funding/ownership bridges before common-equity output.</p></details>`;
}

export function researchOverviewHTML(library){
 return `<details class="research-card"><summary>All 14 reviewed operating cases</summary><p>Immutable source cases, before your local edits. Values are at different forecast origins and use October 17 research. Do not aggregate USD and TWD.</p>${table('Reviewed annual research overview',['Company','Forecast origin','Currency','Operating EV','Years'],library.companies.map(c=>{const r=calculateResearchOperating(researchDraftFor(c));return [`<button class="text-button" data-research-company="${esc(c.ticker)}">${esc(c.ticker)}</button>`,esc(c.valuationTiming.discountOrigin),esc(c.currency),amount(r.enterprise,c.currency),r.rows.length];}))}</details>`;
}

export async function mountResearchWorkspace(root,{fetcher=globalThis.fetch,storage=globalThis.localStorage,download,simulationMount}={}){
 const response=await fetcher(RESEARCH_PATH);if(!response?.ok)throw Error('The renewed annual-research package could not be loaded. The legacy Studio remains available.');
 const library=await response.json();if(library?.schemaVersion!==1||!Array.isArray(library.companies)||library.companies.length!==14)throw Error('The reviewed research package is incomplete.');
 const session=new Map(),undo=new Map(),undoRaw=new Map(),undoErrors=new Map();let c,d,identityError=null,retainedRaw=null,storageOkay=true,releaseSimulation=()=>{},simulationGeneration=0;
 const key=()=>RESEARCH_STORAGE_PREFIX+c.ticker;
 const read=k=>{if(session.has(k))return session.get(k);try{return storage?.getItem(k)??null;}catch{storageOkay=false;return null;}};
 const write=(k,value)=>{session.set(k,value);try{storage?.setItem(k,value);}catch{storageOkay=false;}};
 const save=({stamp=true}={})=>{if(stamp&&d&&typeof d==='object')d.updatedAt=new Date().toISOString();write(key(),JSON.stringify(d));write(RESEARCH_STORAGE_PREFIX+'selection',c.ticker);const state=root.querySelector('#research-save-state');if(state)state.textContent=storageOkay?'Annual draft saved on this device':'Storage unavailable · export before leaving';};
 const exportFile=(name,value)=>{if(download)return download(name,value);const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 function choose(ticker){
  c=library.companies.find(x=>x.ticker===ticker)||library.companies[0];let saved=null;retainedRaw=null;const raw=read(key());
  try{if(raw!==null)saved=JSON.parse(raw);}catch{retainedRaw=raw;d={unreadableSavedJSON:raw};identityError='Saved annual draft is not valid JSON. It has been retained for export.';render();return;}
  if(raw!==null&&(saved===null||typeof saved!=='object'||Array.isArray(saved))){retainedRaw=raw;d=saved;identityError='Saved annual draft is an unsupported JSON value. It has been retained for export.';render();return;}
  const restored=restoreResearchDraft(saved,c);d=restored.draft;identityError=restored.error;render();if(!identityError)save();
 }
 function clearSimulation(){simulationGeneration++;releaseSimulation();releaseSimulation=()=>{};}
 async function mountSimulationPanel(){const target=root.querySelector('#research-simulation-root');if(!target||identityError||(typeof document==='undefined'&&!simulationMount))return;const generation=simulationGeneration,activeDraft=d;try{const mount=simulationMount||(await import('./research-simulation-view.js')).mountAnnualResearchSimulation;if(generation!==simulationGeneration||activeDraft!==d)return;releaseSimulation=mount(target,{draft:d,companyCase:c,onConfigChange:config=>{if(generation!==simulationGeneration||activeDraft!==d)return;d.researchSimulationConfig=structuredClone(config);save();}})||(()=>{});}catch(error){if(generation===simulationGeneration&&activeDraft===d)target.innerHTML=`<p class="research-warning">Annual simulation could not be loaded: ${esc(error.message)}. Your deterministic research value remains available.</p>`;}}
 function updateResults(){clearSimulation();const el=root.querySelector('#research-results');if(el)el.innerHTML=researchResultsHTML(c,d,{identityError});bindActions();mountSimulationPanel();}
 function bindActions(){root.querySelectorAll('[data-research-action]').forEach(button=>button.onclick=()=>{
  const action=button.dataset.researchAction;
  if(action==='legacy'){if(typeof document!=='undefined'){const picker=document.querySelector('#current-company');if(picker){picker.value=c.ticker;picker.onchange?.({target:picker});}document.querySelector('[data-tab="current"]')?.click();}return;}
  if(action==='export'){let output;try{output=exportResearchCase(d,c);}catch{output={originalResearchCase:c,retainedDraft:d,...(retainedRaw===null?{}:{rawSavedDraft:retainedRaw}),error:identityError||'Invalid edited inputs; no valuation exported.'};}if(output.operating){if(finite(output.timing.enterprise)){try{output.equityBridge=calculateResearchBridge(d,output.timing.enterprise,{...(d.bridgeInputs||{}),calculationDate:output.timing.date});}catch(e){output.equityBridge={status:'incomplete',equity:null,perShare:null,error:e.message};}}else output.equityBridge={status:'incomplete',equity:null,perShare:null,error:output.timing.message};}exportFile(`${c.ticker}-annual-research-${RESEARCH_VERSION}.json`,output);return;}
  if(action==='undo'){if(!undo.has(c.ticker))return;d=structuredClone(undo.get(c.ticker));retainedRaw=undoRaw.get(c.ticker)??null;identityError=undoErrors.get(c.ticker)||restoreResearchDraft(d,c).error;undo.delete(c.ticker);undoRaw.delete(c.ticker);undoErrors.delete(c.ticker);if(retainedRaw!==null)write(key(),retainedRaw);else save({stamp:false});render();return;}
  if(action==='load'){const loaded=loadAnnualResearchCase(d,c);undo.set(c.ticker,loaded.undo);undoRaw.set(c.ticker,retainedRaw);undoErrors.set(c.ticker,identityError);d=loaded.draft;identityError=null;retainedRaw=null;save();render();return;}
  if(action==='normalize'){try{const next=terminalNormalizedDraft(d);undo.set(c.ticker,structuredClone(d));undoRaw.set(c.ticker,retainedRaw);undoErrors.set(c.ticker,identityError);d=next;identityError=null;save();render();}catch(e){root.querySelector('#research-action-status').textContent=e.message;}return;}
 });}
 function render(){
  clearSimulation();
  const dossier=`./data/renewed-research-2026-10-17/dossiers.html#${c.ticker}`;
  root.innerHTML=`<div class="research-toolbar"><label for="research-company">Company<select id="research-company">${library.companies.map(x=>`<option value="${esc(x.ticker)}" ${x.ticker===c.ticker?'selected':''}>${esc(x.ticker)}</option>`).join('')}</select></label><div><span class="eyebrow">RESEARCH VERSION ${RESEARCH_VERSION}</span><p>Separate annual draft · original sources preserved</p><p class="micro">Load resets the operating path and timing; your notes, claim settings and simulation settings are kept.</p></div><div class="research-actions"><button class="quiet" data-research-action="load">Load original reviewed case</button><button class="quiet" data-research-action="undo" ${undo.has(c.ticker)?'':'disabled'}>Undo last load</button><button class="quiet" data-research-action="export">Export annual case</button></div></div><p id="research-action-status" role="status"></p><p id="research-save-state" class="micro"></p><div class="research-evidence-banner"><b>${esc(c.ticker)} · why these assumptions</b><p>${esc(researchSummaries[c.ticker]?.summary||'')}</p><p>${link(dossier,'Read the full company dossier')} · ${link(`./data/renewed-research-2026-10-17/evidence-${c.ticker}.html#guidance`,'Guidance and outcomes')} · ${link(`./data/renewed-research-2026-10-17/evidence-${c.ticker}.html#management`,'Management evidence')} · ${link('./data/renewed-research-2026-10-17/evidence.json','Structured evidence')}</p><p>Reported facts, management statements and analyst judgments are classified separately. Sources have dated reading scope; coverage is bounded, not a claim to have read every statement.</p></div><div class="research-layout"><div id="research-results" aria-live="polite">${researchResultsHTML(c,d,{identityError})}</div><div id="research-editor">${identityError?'':researchClaimsEditorHTML(c,d)+researchEditorHTML(c,d)}<section class="research-card"><h2>Research notes</h2><label for="research-notes">Your reasoning and next evidence to watch</label><textarea id="research-notes" ${identityError?'disabled':''} data-research-text="notes" rows="4">${esc(d?.notes||'')}</textarea><p class="micro">Your legacy Studio drafts and original research data are not overwritten by this workspace.</p></section></div></div>${researchOverviewHTML(library)}`;
  root.querySelector('#research-company').onchange=e=>choose(e.target.value);
  root.querySelectorAll('[data-research-company]').forEach(button=>button.onclick=()=>choose(button.dataset.researchCompany));
  root.querySelectorAll('[data-research-input]').forEach(el=>el.oninput=()=>{
   const value=el.value.trim()===''?null:Number(el.value)/Number(el.dataset.scale||1),group=el.dataset.researchInput,field=el.dataset.field;
   if(group==='annual')d.annual[Number(el.dataset.index)][field]=value;else if(group==='terminal')d.terminal[field]=value;else if(group==='timing')d.timing[field]=value;else if(group==='bridge'){d.bridgeInputs||={};d.bridgeInputs[field]=value;}
   if(group==='annual'||group==='terminal')d.userEdited=true;save();updateResults();
  });
  root.querySelectorAll('[data-research-text]').forEach(el=>el.oninput=()=>{if(identityError)return;const key=el.dataset.researchText;if(key==='notes')d.notes=el.value;else d.timing[key]=el.value;save();if(key!=='notes')updateResults();});
  root.querySelectorAll('[data-research-claim-select]').forEach(el=>el.onchange=()=>{d.bridgeInputs||={};d.bridgeInputs[el.dataset.researchClaimSelect]=el.value;save();updateResults();});
  const mode=root.querySelector('#research-timing-mode');if(mode)mode.onchange=()=>{d.timing.mode=mode.value;save();updateResults();};
  bindActions();mountSimulationPanel();
 }
 choose(read(RESEARCH_STORAGE_PREFIX+'selection')||'AAPL');
 return {choose,getState:()=>({company:structuredClone(c),draft:structuredClone(d),identityError}),destroy(){clearSimulation();root.innerHTML='';}};
}

if(typeof document!=='undefined'){
 const root=document.querySelector('#renewed-research-app');
 if(root)mountResearchWorkspace(root).catch(e=>{root.innerHTML=`<div class="error">${esc(e.message)}</div>`;});
 const open=document.querySelector('#open-renewed-research');if(open)open.onclick=e=>{e.preventDefault();document.querySelector('[data-tab="renewed"]')?.click();};
}
